//! Extension grammar rules — the productions petitpy adds on top of
//! vendor `py/grammar.h`.
//!
//! Port of `src/compiler/grammar_ext.zig`.
//!
//! `grammar_data.rs` is generated from vendor grammar.h and pinned by
//! SHA-256; vendor/ is regenerated by `make port` and must not be
//! hand-edited. So rules we add live here instead, in ids NUM_RULES..255
//! (rule ids are u8 and vendor stops at 183), and the parser widens its
//! two table lookups to consult this file above that boundary. The
//! generated file stays byte-identical to the C shim.
//!
//! Extension rules run on the unmodified parser engine: same act/arg
//! encoding, same AND/OR/LIST handling, same node building.

#![allow(non_upper_case_globals)]
//!
//! ── The match statement ──────────────────────────────────────────────
//!
//! `match` and `case` are soft keywords with no TokenKind of their own
//! (see the lexer's SOFT KEYWORDS section), so both rules start on a
//! bare `tok(NAME)`. That is only sound because the sole entry point is
//! the parser's soft-keyword hook, which has already checked the text
//! and confirmed a trailing ':' via peek_line_ends_with_colon(). Nothing
//! reaches match_stmt by ordinary alternative-matching.
//!
//! Patterns are parsed as *expressions* rather than given a pattern
//! grammar of their own. CPython needs one because PEG wants precision;
//! we don't, because every pattern form except two is already a valid
//! expression:
//!
//!     case 1:            literal    -> expr
//!     case x:            capture    -> expr (NAME)
//!     case 1 | 2:        or-pattern -> expr ('|' is bitwise-or level)
//!     case [a, *rest]:   sequence   -> exprlist_2 (star_expr | expr)
//!     case P(x=1):       class      -> expr (call with keywords)
//!     case {'k': v}:     mapping    -> expr (dict display)
//!
//! The two that aren't expressions get a rule each: `as` bindings and
//! `if` guards. Interpreting the resulting expression tree as a pattern
//! is the compiler's job.

use crate::compiler::grammar_data as grammar;
use crate::compiler::lexer::TokenKind;

/// Rule ids continue where the generated table stops.
pub const RULE_match_stmt: u8 = grammar::NUM_RULES as u8;
pub const RULE_match_stmt_case_list: u8 = RULE_match_stmt + 1;
pub const RULE_match_stmt_case: u8 = RULE_match_stmt + 2;
pub const RULE_match_stmt_patterns: u8 = RULE_match_stmt + 3;
pub const RULE_match_stmt_pattern: u8 = RULE_match_stmt + 4;
pub const RULE_match_stmt_alts: u8 = RULE_match_stmt + 5;
pub const RULE_match_stmt_alt: u8 = RULE_match_stmt + 6;
pub const RULE_match_stmt_as: u8 = RULE_match_stmt + 7;
pub const RULE_match_stmt_guard: u8 = RULE_match_stmt + 8;

pub const NUM_EXT_RULES: usize = 9;
pub const LAST_RULE: usize = grammar::NUM_RULES + NUM_EXT_RULES;

// Mirrors the DEF_RULE macros in vendor grammar.h — see parse.c:79-85.
const OR_: u8 = grammar::RULE_ACT_OR;
const AND_: u8 = grammar::RULE_ACT_AND;
const LIST_: u8 = grammar::RULE_ACT_LIST;
const IDENT: u8 = grammar::RULE_ACT_ALLOW_IDENT;
const ONE_OR_MORE: u8 = LIST_ | 2;
const LIST_NO_END: u8 = LIST_ | 1;

const fn tok(t: TokenKind) -> u16 {
    grammar::RULE_ARG_TOK | (t as u16)
}
const fn rule(id: u8) -> u16 {
    grammar::RULE_ARG_RULE | (id as u16)
}
const fn opt(id: u8) -> u16 {
    grammar::RULE_ARG_OPT_RULE | (id as u16)
}

// match_stmt: NAME namedexpr_test ':' NEWLINE INDENT case+ DEDENT
const ARGS_MATCH_STMT: &[u16] = &[
    tok(TokenKind::NAME),
    rule(grammar::RULE_namedexpr_test),
    tok(TokenKind::DEL_COLON),
    tok(TokenKind::NEWLINE),
    tok(TokenKind::INDENT),
    rule(RULE_match_stmt_case_list),
    tok(TokenKind::DEDENT),
];
const ARGS_CASE_LIST: &[u16] = &[rule(RULE_match_stmt_case)];
// case: NAME patterns [guard] ':' suite
const ARGS_CASE: &[u16] = &[
    tok(TokenKind::NAME),
    rule(RULE_match_stmt_patterns),
    opt(RULE_match_stmt_guard),
    tok(TokenKind::DEL_COLON),
    rule(grammar::RULE_suite),
];
// patterns: pattern (',' pattern)*   — no trailing comma, matching
// CPython's open_sequence_pattern.
const ARGS_PATTERNS: &[u16] = &[rule(RULE_match_stmt_pattern), tok(TokenKind::DEL_COMMA)];
// pattern: alts ['as' NAME]
const ARGS_PATTERN: &[u16] = &[rule(RULE_match_stmt_alts), opt(RULE_match_stmt_as)];
// alts: alt ('|' alt)*
//
// The `|` has to be consumed HERE, not left to `expr`. Vendor's parser
// folds constant binary ops as it builds nodes (parser.rs
// fold_small_int_bin_op), so `case 1 | 2:` routed through `expr` arrives at
// the compiler as the small int 3 — an or-pattern silently turned into
// a bitwise-or. Binding `|` at this level, over `xor_expr` (the
// precedence rung below `|`), keeps the alternatives apart.
const ARGS_ALTS: &[u16] = &[rule(RULE_match_stmt_alt), tok(TokenKind::OP_PIPE)];
const ARGS_ALT: &[u16] = &[
    rule(grammar::RULE_star_expr),
    rule(grammar::RULE_xor_expr),
];
const ARGS_AS: &[u16] = &[tok(TokenKind::KW_AS), tok(TokenKind::NAME)];
const ARGS_GUARD: &[u16] = &[tok(TokenKind::KW_IF), rule(grammar::RULE_namedexpr_test)];

const EXT_ACT: [u8; NUM_EXT_RULES] = [
    AND_ | 7,           // match_stmt
    ONE_OR_MORE,        // case_list
    AND_ | 5,           // case
    LIST_NO_END | 2,    // patterns
    AND_ | 2 | IDENT,   // pattern — collapses to the bare alt when no `as`
    LIST_NO_END | 2,    // alts — collapses to the bare alt when no `|`
    OR_ | 2,            // alt
    AND_ | 2,           // as    — no ident: stays a node so the compiler can
    AND_ | 2,           // guard   test for it by kind rather than by position
];

const EXT_ARGS: [&[u16]; NUM_EXT_RULES] = [
    ARGS_MATCH_STMT,
    ARGS_CASE_LIST,
    ARGS_CASE,
    ARGS_PATTERNS,
    ARGS_PATTERN,
    ARGS_ALTS,
    ARGS_ALT,
    ARGS_AS,
    ARGS_GUARD,
];

/// Is `id` an extension rule (at or above NUM_RULES)?
pub fn is_ext(id: u8) -> bool {
    (id as usize) >= grammar::NUM_RULES
}

/// Widened `grammar::rule_act` — vendor table below NUM_RULES, ours above.
pub fn rule_act(id: u8) -> u8 {
    if is_ext(id) {
        EXT_ACT[id as usize - grammar::NUM_RULES]
    } else {
        grammar::rule_act(id)
    }
}

/// Widened `grammar::get_rule_arg`.
pub fn get_rule_arg(id: u8) -> &'static [u16] {
    if is_ext(id) {
        EXT_ARGS[id as usize - grammar::NUM_RULES]
    } else {
        grammar::get_rule_arg(id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Port of the Zig `comptime` block: rule ids fit in u8, and each
    /// act's arg count matches the arg array it indexes, or the parser
    /// walks off the end of the slice.
    #[test]
    fn ext_rule_ids_and_arg_counts() {
        // Rule ids are u8 everywhere (parser.rs push_rule, Pn struct kinds).
        assert!(LAST_RULE <= 256);
        for (i, (&act, &args)) in EXT_ACT.iter().zip(EXT_ARGS.iter()).enumerate() {
            let n = (act & grammar::RULE_ACT_ARG_MASK) as usize;
            let want = if act & grammar::RULE_ACT_KIND_MASK == LIST_ {
                // LIST acts encode repetition in the low bits, not an arg
                // count: `one_or_more` takes 1 arg, the others 2.
                if act == ONE_OR_MORE {
                    1
                } else {
                    2
                }
            } else {
                n
            };
            assert_eq!(args.len(), want, "ext rule {i} arg count mismatch");
        }
    }

    #[test]
    fn rule_ids_continue_from_num_rules() {
        assert_eq!(grammar::NUM_RULES as u8, RULE_match_stmt);
        assert_eq!(grammar::NUM_RULES as u8 + 8, RULE_match_stmt_guard);
        assert_eq!(9, NUM_EXT_RULES);
        assert_eq!(grammar::NUM_RULES + NUM_EXT_RULES, LAST_RULE);
    }

    #[test]
    fn widened_lookups_agree_with_vendor_below_num_rules() {
        for id in 0..grammar::NUM_RULES as u8 {
            assert_eq!(grammar::rule_act(id), rule_act(id));
            assert_eq!(grammar::get_rule_arg(id), get_rule_arg(id));
        }
    }
}
